package com.quickcart.controller; import com.quickcart.entity.CustomerOrder; import com.quickcart.dto.OrderRequest; import com.quickcart.service.OrderService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/orders") public class OrderController {final OrderService s;OrderController(OrderService x){s=x;} @PostMapping CustomerOrder create(@RequestBody OrderRequest r){return s.create(r);} @GetMapping List<CustomerOrder> list(@RequestParam Long customerId){return s.list(customerId);} @GetMapping("/{id}") CustomerOrder one(@PathVariable Long id){return s.one(id);} }
